GOAL = ("A support agent in Foundry Agent Service must keep each customer's conversation history across a chat that can span several days and devices. "
        "**Goal:** all conversation data must be stored at rest in Azure resources that the company owns, and only generally available features may be used.")
def S(i, sol, ans, prem, apply, rule):
    return dict(id="m2-s" + str(i), type="solution", skill=D2, scenario=GOAL, stem="**Proposed solution:** " + sol + " Does this meet the goal?", answer=ans,
                think=T(prem, [["Agent state in your own resources","Setup","Standard setup (your Cosmos DB, Storage, AI Search)"],["Microsoft-managed storage","Setup","Basic setup"],["Facts about a user across chats","Preview","Memory"]],
                        apply, rule, G_ROLES),
                eli5="Keep the case files in your own filing cabinet, not the landlord's, and don't rely on a filing system still on trial.", learn=L+"agents/concepts/standard-agent-setup")
A += [
 S(1, "You create the project with the Standard agent setup, connecting your own Azure Cosmos DB, Storage and AI Search resources, and the app reuses one conversation per customer chat by its ID.", True,
   "That keeping history needs a special feature. Conversations already persist; the setup decides where they're stored.",
   [["\"Standard agent setup ... your own Azure Cosmos DB\"","Conversations stored in your resources: met."],["\"reuses one conversation ... by its ID\"","GA conversation state across days and devices: met."]], "Standard setup stores conversations and responses in your own Cosmos DB."),
 S(2, "You create the project with the Basic agent setup, and the app reuses one conversation per customer chat by its ID.", False,
   "That all setups store data the same way. Basic setup uses Microsoft-managed resources.",
   [["\"Basic agent setup\"","Data at rest in Microsoft-managed storage: not met."],["\"reuses one conversation\"","Continuity is fine, but one failure is enough."]], "Basic = Microsoft-managed storage; Standard = bring your own."),
 S(3, "You create the project with the Standard agent setup, and the agent uses memory scoped to each customer, instead of conversations, to hold the chat history.", False,
   "That memory is the way to keep a chat going. Memory is preview, and it keeps extracted facts, not the full history.",
   [["\"uses memory\"","Preview: not met."],["\"Standard agent setup\"","Storage is fine, but one failure is enough."]], "Within a chat, use conversations; memory (preview) is for facts across chats."),
]
